/** The measured timing of one surah as timing entries (ayahs 1..N), or null when there is none. */
export function measuredTimingEntries(reciterId: string, surah: number): TimingEntry[] | null {
  const deltas = MEASURED[reciterId]?.[surah];
  if (!deltas || deltas.length < 2) return null;
  const entries: TimingEntry[] = [];
  let at = deltas[0];
  for (let k = 1; k < deltas.length; k++) {
    entries.push({ ayah: k, startMs: at, endMs: at + deltas[k] });
    at += deltas[k];
  }
  return entries;
}
